fn sum(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // Since a and b have the same length, we can zip them together.
    // We pre-allocate the result vector for efficiency.
    let mut c = Vec::with_capacity(a.len());
    for (&x, &y) in a.iter().zip(b.iter()) {
        c.push(x + y);
    }
    c
}

fn main() {
    // Example usage:
    let v1 = vec![1, 2, 3, 10];
    let v2 = vec![4, 5, 6, 20];
    let result = sum(&v1, &v2);
    println!("{:?}", result); // Should print [5, 7, 9, 30]
}